# hermes-terminal: plain `hermes` opens the conversation "Hermes's Terminal" (pinned in the Hermes app)
# with a recap of where you stopped. `hermes-new` = a separate new conversation. Generated by setup.py.
$HermesTerminalScript = '__SCRIPT__'
$HermesTerminalPython = '__PYTHON__'
$global:HermesHooks['open-50-terminal'] = {
    param($exe)
    $started = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds()
    $id = (& $HermesTerminalPython $HermesTerminalScript open 2>$null | Select-Object -Last 1)
    if ($id) { & $exe --resume $id } else { & $exe }
    Write-Host 'Saving the recap...' -ForegroundColor DarkGray
    & $HermesTerminalPython $HermesTerminalScript close $started 2>$null
}
